  "devEnv.warningBodySrt": "AI 可以在任何对话中，在团队服务器上运行任何程序。命令可以读取该对话的人能读取的所有团队文件夹，但只能写入该对话的项目文件夹和这个人自己的文件夹。沙盒会隐藏服务器的数据、密钥、其他人的个人文件夹以及这个人无法打开的文件夹。\n- 命令可以通过允许的网站向外发送数据。GitHub、npm 和 PyPI 都接受上传，所以命令可以把这个人能读取的所有文件发送出去。\n- 当对话提出请求时，每个人都可以为自己的命令允许更多网站，或为自己开启“完整互联网”。之后这个人的命令也可以向这些网站发送数据。无需管理员操作。\n- 命令可以把这个人能读取的文件复制到项目文件夹，让更多人看到。\n- 命令在这个人自己的文件夹中修改的文件没有修改记录，也没有旧版本。\n- 所有能写入项目文件夹的人都使用同一个文件夹。一个人的修改会影响另一个人的下一条命令。\n- 这里没有登录信息。git push 之类的命令请在你自己的电脑上执行。\n- 占用内存过多的运行会被停止。团队的重型任务会排队等待。\n- 命令会记录在活动日志中。\n此功能是实验性的，随时可能关闭。",
