  "teamSettings.aiVision": "将图片、PDF 页面和视频画面发送给 AI",
  "teamSettings.aiVisionHint": "AI 读取照片、截图、扫描的 PDF 页面或视频时，会像 Claude Code 一样直接看图片本身（视频则是均匀间隔的画面）。图片会像其他文件内容一样发送给 AI 服务商（Anthropic 或 OpenAI）。关闭后：不发送任何图片；在 Mac 服务器上 AI 会改为获得识别出的文字，在 Linux 服务器上只有一条说明。在 Linux 服务器上无法搜索扫描文档的文字。",
  "teamSettings.aiSubagents": "允许 AI 将工作拆分为子任务",
  "teamSettings.aiSubagentsHint": "像 Claude Code 一样，AI 可以把大请求的部分工作交给同时工作的辅助 AI（最多 4 个）。辅助 AI 拥有相同的工具，只能看到提问者能看到的内容；它的步骤显示在回答下方，审计日志会记录它的调用。辅助 AI 也会使用 AI 服务，因此大请求的费用可能更高。关闭后：AI 自己完成所有工作。",
  "teamSettings.answerStepLimit": "每个回答的工具轮数",
